const body = items[0].json.body || items[0].json;
const data = body.data || {};

const formattedAmount = data.amount ? `₱${Number(data.amount).toLocaleString()}` : 'In-Kind Items';
const receiptSubject = `Thank You for Your Donation to Pawlse [Ref: ${data.reference_number || 'N/A'}]`;
const receiptBody = `Dear ${data.donor_name || 'Kind Donor'},\n\nThank you for your generous contribution to the animals of Pawlse!\n\nDonation Details:\n• Reference: ${data.reference_number || 'N/A'}\n• Type: ${data.type || 'Donation'}\n• Contribution: ${formattedAmount}\n• Date: ${data.submitted_at}\n\nYour compassion helps provide food, shelter, and medical care for rescued animals in need.\n\nWarm regards,\nThe Pawlse Team`;

return [{
  json: {
    eventId: body.event_id,
    donationId: data.donation_id,
    donorName: data.donor_name,
    donorEmail: data.donor_email,
    amount: formattedAmount,
    receiptSubject: receiptSubject,
    receiptBody: receiptBody
  }
}];
